#!/usr/bin/env python3
"""Restock Dispatch Console - a small server-rendered web application.

Started through the trusted launcher, so it runs as the unprivileged service
account `appsvc` and keeps all of its state under /var/lib/harbor-service,
which is mode 0700 and owned by that account.  The solver account can neither
read nor write it, which is what makes the recorded decisions distinguishable
from a file the solver could have written.

Every state change must arrive as a real browser form navigation carrying a
single-use token that only ever appeared in a page the browser actually
rendered, redeemed by the same session that was handed it.

Determinism note: nothing that varies per instance is written to disk.  Tokens
and the event log live in process memory, so /var/lib/harbor-service/console.db
is byte-identical on every fresh instance until a decision is actually
recorded.
"""

import html
import json
import os
import secrets
import sqlite3
import sys
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlparse

STATE_DIR = "/var/lib/harbor-service"
DB_PATH = os.path.join(STATE_DIR, "console.db")
MANIFEST_PATH = os.path.join(STATE_DIR, "dispatch_manifest.json")
ORIGIN = "http://127.0.0.1:8099"
PORT = 8099

# ---------------------------------------------------------------- seed data --
# Deterministic: identical on every fresh instance.  tests/verify.py carries an
# independent copy of these literals and fails the task if the rows differ.
DEPARTMENTS = [
    ("OPS", "Operations", 500000),
    ("LAB", "Laboratory", 300000),
    ("FAC", "Facilities", 250000),
]

VENDORS = [
    ("V-ACME", "Acme Supply Co", 1),
    ("V-BOREAL", "Boreal Industrial", 1),
    ("V-CRESTLINE", "Crestline Partners", 1),
    ("V-DELTAWORKS", "Deltaworks Trading", 0),
    ("V-EASTGATE", "Eastgate Wholesale", 0),
]

CATALOG = [
    ("ITM-100", "Nitrile gloves (box of 100)", 2400),
    ("ITM-200", "Pipette tips (case)", 8800),
    ("ITM-300", "Safety goggles", 1950),
    ("ITM-400", "Anti-fatigue floor mat", 14000),
    ("ITM-500", "Thermal label printer", 32000),
]

# (id, department, vendor, item, quantity, unit price in cents, requester)
REQUISITIONS = [
    ("R001", "OPS", "V-ACME", "ITM-100", 40, 2200, "M. Okafor"),
    ("R002", "LAB", "V-DELTAWORKS", "ITM-200", 10, 8000, "P. Lindqvist"),
    ("R003", "LAB", "V-BOREAL", "ITM-200", 12, 9250, "P. Lindqvist"),
    ("R004", "FAC", "V-CRESTLINE", "ITM-400", 20, 13500, "S. Duarte"),
    ("R005", "OPS", "V-BOREAL", "ITM-300", 60, 1800, "M. Okafor"),
    ("R006", "LAB", "V-CRESTLINE", "ITM-200", 30, 8800, "H. Nakamura"),
    ("R007", "LAB", "V-ACME", "ITM-500", 1, 31000, "H. Nakamura"),
    ("R008", "FAC", "V-EASTGATE", "ITM-400", 5, 15000, "S. Duarte"),
]

REASON_CODES = ("VENDOR", "PRICE", "BUDGET")

LOCK = threading.RLock()
DB = None

# In-memory only, so the on-disk state stays byte-stable across instances.
# token -> {"scope": <req id or "__finalize__">, "sid": <session id>}
TOKENS = {}
EVENTS = []


def money(cents):
    return "%d.%02d" % (cents // 100, cents % 100)


def log_event(kind, detail):
    EVENTS.append((kind, detail))
    sys.stderr.write("[console] %s :: %s\n" % (kind, detail))
    sys.stderr.flush()


# ------------------------------------------------------------------ storage --
def init_state():
    global DB
    if not os.path.isdir(STATE_DIR):
        raise SystemExit(
            "state directory %s does not exist; the image must provide it "
            "owned by the service account" % STATE_DIR
        )
    if not os.access(STATE_DIR, os.W_OK | os.X_OK):
        raise SystemExit(
            "state directory %s is not writable by uid %d"
            % (STATE_DIR, os.geteuid())
        )

    fresh = not os.path.exists(DB_PATH)
    DB = sqlite3.connect(DB_PATH, check_same_thread=False)
    DB.row_factory = sqlite3.Row
    DB.executescript(
        """
        CREATE TABLE IF NOT EXISTS departments(
            code TEXT PRIMARY KEY, name TEXT, budget_cents INTEGER);
        CREATE TABLE IF NOT EXISTS vendors(
            code TEXT PRIMARY KEY, name TEXT, approved INTEGER);
        CREATE TABLE IF NOT EXISTS catalog(
            item TEXT PRIMARY KEY, name TEXT, cap_cents INTEGER);
        CREATE TABLE IF NOT EXISTS requisitions(
            id TEXT PRIMARY KEY, dept TEXT, vendor TEXT, item TEXT,
            qty INTEGER, unit_cents INTEGER, requester TEXT);
        CREATE TABLE IF NOT EXISTS decisions(
            req_id TEXT PRIMARY KEY, decision TEXT, reason TEXT,
            seq INTEGER, ua TEXT, referer TEXT, fetch_grade TEXT);
        CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, v TEXT);
        """
    )
    if fresh:
        DB.executemany("INSERT INTO departments VALUES (?,?,?)", DEPARTMENTS)
        DB.executemany("INSERT INTO vendors VALUES (?,?,?)", VENDORS)
        DB.executemany("INSERT INTO catalog VALUES (?,?,?)", CATALOG)
        DB.executemany(
            "INSERT INTO requisitions VALUES (?,?,?,?,?,?,?)", REQUISITIONS
        )
        DB.execute("INSERT OR REPLACE INTO meta VALUES ('finalized','0')")
    DB.commit()


def next_seq():
    row = DB.execute("SELECT COALESCE(MAX(seq),0) AS s FROM decisions").fetchone()
    return int(row["s"]) + 1


def remaining_budget():
    """Remaining budget per department given the decisions recorded so far."""
    rem = {code: budget for code, _n, budget in DEPARTMENTS}
    rows = DB.execute(
        "SELECT r.dept AS dept, r.qty AS qty, r.unit_cents AS unit_cents "
        "FROM decisions d JOIN requisitions r ON r.id = d.req_id "
        "WHERE d.decision = 'APPROVE'"
    ).fetchall()
    for row in rows:
        rem[row["dept"]] -= row["qty"] * row["unit_cents"]
    return rem


def decisions_map():
    return {
        row["req_id"]: (row["decision"], row["reason"] or "")
        for row in DB.execute("SELECT req_id, decision, reason FROM decisions")
    }


def is_finalized():
    row = DB.execute("SELECT v FROM meta WHERE k='finalized'").fetchone()
    return bool(row) and row["v"] == "1"


# -------------------------------------------------------------------- tokens --
def issue_token(scope, sid):
    """Hand out a single-use form token bound to this scope and session.

    The token only ever reaches the caller inside a rendered page, so redeeming
    one proves the page was actually fetched by the session that submits it.
    """
    token = secrets.token_hex(16)
    TOKENS[token] = {"scope": scope, "sid": sid}
    # Bound memory: a long run re-renders pages many times.
    if len(TOKENS) > 4096:
        for stale in list(TOKENS)[:2048]:
            TOKENS.pop(stale, None)
    return token


def consume_token(token, scope, sid):
    rec = TOKENS.pop(token, None)
    if rec is None:
        return False
    return rec["scope"] == scope and rec["sid"] == sid


# ------------------------------------------------------------------ manifest --
def write_manifest():
    """Write the dispatch manifest.

    Lives in the 0700 service-account state directory, so only the console can
    create it.  The verifier cross-checks it against the console's own
    decisions table.
    """
    rows = DB.execute(
        "SELECT req_id, decision, reason, seq FROM decisions ORDER BY req_id"
    ).fetchall()
    doc = {
        "console": "restock-dispatch-console",
        "decisions": [
            {
                "id": r["req_id"],
                "decision": r["decision"],
                "reason": r["reason"] or "",
                "seq": r["seq"],
            }
            for r in rows
        ],
    }
    tmp = MANIFEST_PATH + ".tmp"
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w") as fh:
        json.dump(doc, fh, sort_keys=True, separators=(",", ":"))
    os.replace(tmp, MANIFEST_PATH)


# ------------------------------------------------------------------- render --
PAGE = """<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<title>Restock Dispatch Console</title>
<style>
body{font-family:DejaVu Sans,Arial,sans-serif;margin:24px;color:#15202b}
table{border-collapse:collapse;margin:12px 0}
td,th{border:1px solid #b8c4d0;padding:6px 10px;text-align:left}
th{background:#eef3f8}
.nav a{margin-right:16px}
.pending{color:#a8500a;font-weight:bold}
.done{color:#0a6b2d}
</style></head><body>
<h1 id="console-title">Restock Dispatch Console</h1>
<div class="nav"><a id="nav-home" href="/">Queue</a>
<a id="nav-catalog" href="/catalog">Item catalog</a>
<a id="nav-vendors" href="/vendors">Vendor register</a></div>
%s
</body></html>"""


def index_page(sid, message=""):
    rem = remaining_budget()
    dec = decisions_map()
    out = []
    if message:
        out.append('<p id="flash">%s</p>' % html.escape(message))
    out.append(
        '<h2>Department budgets</h2><table id="budget-table"><tr>'
        "<th>Department</th><th>Code</th><th>Annual budget</th>"
        "<th>Remaining</th></tr>"
    )
    for code, name, budget in DEPARTMENTS:
        out.append(
            '<tr id="budget-%s"><td>%s</td><td>%s</td><td>%s</td>'
            '<td class="remaining" id="remaining-%s">%s</td></tr>'
            % (code, html.escape(name), code, money(budget), code,
               money(rem[code]))
        )
    out.append("</table>")

    out.append(
        '<h2>Requisition queue</h2><table id="queue"><tr><th>ID</th>'
        "<th>Dept</th><th>Vendor</th><th>Item</th><th>Qty</th>"
        "<th>Unit price</th><th>Total</th><th>Status</th></tr>"
    )
    for rid, dept, vendor, item, qty, unit, _req in REQUISITIONS:
        if rid in dec:
            d, reason = dec[rid]
            status = '<span class="done">%s%s</span>' % (
                d, (" / " + reason) if reason else ""
            )
        else:
            status = '<span class="pending">PENDING</span>'
        out.append(
            '<tr id="row-%s"><td><a id="open-%s" href="/req/%s">%s</a></td>'
            "<td>%s</td><td>%s</td><td>%s</td><td>%d</td><td>%s</td><td>%s</td>"
            "<td>%s</td></tr>"
            % (rid, rid, rid, rid, dept, vendor, item, qty, money(unit),
               money(qty * unit), status)
        )
    out.append("</table>")

    pending = [r[0] for r in REQUISITIONS if r[0] not in dec]
    if is_finalized():
        out.append(
            '<p id="finalized-note">Dispatch run finalized. '
            "The manifest has been written by the console.</p>"
        )
    elif pending:
        out.append(
            '<p id="pending-note">Still pending: %s</p>'
            % html.escape(", ".join(pending))
        )
    else:
        out.append(
            '<form id="finalize-form" method="post" action="/finalize">'
            '<input type="hidden" name="token" value="%s">'
            '<button id="finalize" type="submit">Finalize dispatch run</button>'
            "</form>" % issue_token("__finalize__", sid)
        )
    return PAGE % "\n".join(out)


def catalog_page():
    out = [
        "<h2>Item catalog</h2><p>Approved unit-price ceiling per item.</p>",
        '<table id="catalog-table"><tr><th>Item</th><th>Description</th>'
        "<th>Price ceiling</th></tr>",
    ]
    for item, name, cap in CATALOG:
        out.append(
            '<tr id="cat-%s"><td>%s</td><td>%s</td>'
            '<td class="cap">%s</td></tr>'
            % (item, item, html.escape(name), money(cap))
        )
    out.append("</table>")
    return PAGE % "\n".join(out)


def vendors_page():
    out = [
        "<h2>Vendor register</h2>",
        '<table id="vendor-table"><tr><th>Vendor</th><th>Name</th>'
        "<th>Status</th></tr>",
    ]
    for code, name, approved in VENDORS:
        out.append(
            '<tr id="ven-%s"><td>%s</td><td>%s</td>'
            '<td class="status">%s</td></tr>'
            % (code, code, html.escape(name),
               "APPROVED" if approved else "NOT APPROVED")
        )
    out.append("</table>")
    return PAGE % "\n".join(out)


def req_page(rid, sid, error=""):
    row = DB.execute("SELECT * FROM requisitions WHERE id=?", (rid,)).fetchone()
    if row is None:
        return None
    dec = decisions_map().get(rid)
    out = ['<h2 id="req-title">Requisition %s</h2>' % rid]
    if error:
        out.append('<p id="form-error">%s</p>' % html.escape(error))
    out.append(
        '<table id="req-detail">'
        '<tr><th>Requisition</th><td id="d-id">%s</td></tr>'
        '<tr><th>Department</th><td id="d-dept">%s</td></tr>'
        '<tr><th>Requester</th><td id="d-requester">%s</td></tr>'
        '<tr><th>Vendor</th><td id="d-vendor">%s</td></tr>'
        '<tr><th>Item</th><td id="d-item">%s</td></tr>'
        '<tr><th>Quantity</th><td id="d-qty">%d</td></tr>'
        '<tr><th>Unit price</th><td id="d-unit">%s</td></tr>'
        '<tr><th>Order total</th><td id="d-total">%s</td></tr></table>'
        % (rid, row["dept"], html.escape(row["requester"]), row["vendor"],
           row["item"], row["qty"], money(row["unit_cents"]),
           money(row["qty"] * row["unit_cents"]))
    )
    if dec:
        out.append(
            '<p id="already-decided">Recorded decision: %s %s</p>'
            % (dec[0], html.escape(dec[1]))
        )
    out.append(
        '<form id="decision-form" method="post" action="/decide">'
        '<input type="hidden" name="req_id" value="%s">'
        '<input type="hidden" name="token" value="%s">'
        '<p><label><input type="radio" id="decision-approve" name="decision" '
        'value="APPROVE"> Approve</label><br>'
        '<label><input type="radio" id="decision-reject" name="decision" '
        'value="REJECT"> Reject</label></p>'
        '<p><label for="reason">Rejection reason code '
        "(VENDOR, PRICE or BUDGET; leave blank when approving)</label><br>"
        '<input type="text" id="reason" name="reason" value="" '
        'autocomplete="off" size="16"></p>'
        '<button id="submit-decision" type="submit">Record decision</button>'
        "</form>" % (rid, issue_token(rid, sid))
    )
    return PAGE % "\n".join(out)


# -------------------------------------------------------------------- server --
def grade_fetch(headers):
    """Record how browser-like a mutating request looked (diagnostic only)."""
    bits = []
    strict = True
    for name, want in (
        ("sec-fetch-dest", "document"),
        ("sec-fetch-mode", "navigate"),
        ("sec-fetch-site", "same-origin"),
    ):
        got = (headers.get(name) or "").lower()
        bits.append("%s=%s" % (name.split("-")[-1], got or "-"))
        if got != want:
            strict = False
    return ("strict" if strict else "weak"), ";".join(bits)


class Handler(BaseHTTPRequestHandler):
    server_version = "RestockConsole/1.0"
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *args):
        pass

    # -- helpers
    def _send(self, code, body, ctype="text/html; charset=utf-8", extra=None):
        data = body.encode() if isinstance(body, str) else body
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        for key, value in extra or []:
            self.send_header(key, value)
        self.end_headers()
        self.wfile.write(data)

    def _redirect(self, location):
        self.send_response(303)
        self.send_header("Location", location)
        self.send_header("Content-Length", "0")
        self.end_headers()

    def _sid(self):
        cookie = self.headers.get("cookie") or ""
        for part in cookie.split(";"):
            part = part.strip()
            if part.startswith("hsid="):
                return part[5:]
        return ""

    def do_GET(self):
        path = urlparse(self.path).path
        with LOCK:
            if path == "/healthz":
                return self._send(
                    200, "ok\n", ctype="text/plain; charset=utf-8"
                )
            sid = self._sid()
            extra = []
            if not sid:
                sid = secrets.token_hex(12)
                extra = [
                    (
                        "Set-Cookie",
                        "hsid=%s; Path=/; HttpOnly; SameSite=Strict" % sid,
                    )
                ]
            if path == "/":
                return self._send(200, index_page(sid), extra=extra)
            if path == "/catalog":
                return self._send(200, catalog_page(), extra=extra)
            if path == "/vendors":
                return self._send(200, vendors_page(), extra=extra)
            if path.startswith("/req/"):
                page = req_page(path[5:], sid)
                if page is None:
                    return self._send(
                        404,
                        PAGE % '<p id="err">No such requisition.</p>',
                        extra=extra,
                    )
                return self._send(200, page, extra=extra)
            return self._send(
                404, PAGE % '<p id="err">Not found.</p>', extra=extra
            )

    def _read_form(self):
        try:
            length = int(self.headers.get("content-length") or "0")
        except ValueError:
            length = 0
        raw = (
            self.rfile.read(length).decode("utf-8", "replace") if length else ""
        )
        return {k: v[0] for k, v in parse_qs(raw, keep_blank_values=True).items()}

    def _reject(self, why, detail):
        log_event("rejected", "%s :: %s" % (why, detail))
        self._send(
            403, PAGE % ('<p id="err">Rejected: %s</p>' % html.escape(why))
        )

    def do_POST(self):
        path = urlparse(self.path).path
        form = self._read_form()
        with LOCK:
            sid = self._sid()
            ua = self.headers.get("user-agent") or ""
            referer = self.headers.get("referer") or ""
            origin = self.headers.get("origin") or ""
            grade, bits = grade_fetch(self.headers)
            fingerprint = "ua=%r referer=%r origin=%r %s" % (
                ua,
                referer,
                origin,
                bits,
            )

            if "Chrome/" not in ua:
                return self._reject(
                    "this console only accepts decisions made in the browser "
                    "console window",
                    fingerprint,
                )
            if origin and origin != ORIGIN:
                return self._reject("cross-origin submission", fingerprint)
            if not sid:
                return self._reject(
                    "no console session; open the queue page first", fingerprint
                )

            if path == "/decide":
                rid = form.get("req_id", "")
                if referer != ORIGIN + "/req/" + rid:
                    return self._reject(
                        "decision was not submitted from the requisition page",
                        fingerprint,
                    )
                row = DB.execute(
                    "SELECT * FROM requisitions WHERE id=?", (rid,)
                ).fetchone()
                if row is None:
                    return self._reject("unknown requisition", fingerprint)
                if is_finalized():
                    return self._reject(
                        "dispatch run already finalized", fingerprint
                    )
